package com.yep.dao;

import com.yep.model.Certificate;
import com.yep.util.DatabaseConnection;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

/**
 * CertificateDAO — database operations for certificates (FR19, FR20).
 *
 * The eligibility rules live in CertificateService; this class only
 * reads and writes the certificates table.
 */
public class CertificateDAO {

    /**
     * Saves a new certificate with a fresh verification code and returns it.
     * The code is generated by Certificate.generateCode() (format YEP-XXXX-XXXX).
     */
    public Certificate issue(int participantId, String certType) throws SQLException {
        String sql = "INSERT INTO certificates (participant_id, cert_type, " +
                     "verification_code, issued_date) VALUES (?, ?, ?, CURDATE())";

        // Retry in the (very unlikely) case that a random code already exists
        for (int attempt = 0; attempt < 5; attempt++) {
            String code = Certificate.generateCode();
            if (findByCode(code) != null) continue;

            try (Connection conn = DatabaseConnection.getConnection();
                 PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

                ps.setInt(1, participantId);
                ps.setString(2, certType);
                ps.setString(3, code);
                ps.executeUpdate();

                try (ResultSet keys = ps.getGeneratedKeys()) {
                    keys.next();
                    return new Certificate(keys.getInt(1), participantId, certType,
                                           code, java.time.LocalDate.now());
                }
            }
        }
        throw new SQLException("Could not generate a unique verification code.");
    }

    /** Returns all certificates for a participant. */
    public List<Certificate> findByParticipant(int participantId) throws SQLException {
        String sql = "SELECT * FROM certificates WHERE participant_id = ? ORDER BY issued_date DESC";
        List<Certificate> list = new ArrayList<>();

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, participantId);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) list.add(mapRow(rs));
            }
        }
        return list;
    }

    /** Returns every certificate, newest first (admin view). */
    public List<Certificate> findAll() throws SQLException {
        String sql = "SELECT * FROM certificates ORDER BY issued_date DESC, certificate_id DESC";
        List<Certificate> list = new ArrayList<>();

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) list.add(mapRow(rs));
        }
        return list;
    }

    /**
     * Looks up a certificate by its verification code (FR20).
     * Used by the public verification page — no login required.
     * Returns null if the code is not found.
     */
    public Certificate findByCode(String verificationCode) throws SQLException {
        if (verificationCode == null) return null;
        String sql = "SELECT * FROM certificates WHERE verification_code = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, verificationCode.trim().toUpperCase());
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return mapRow(rs);
            }
        }
        return null;
    }

    /** Checks whether a participant already has a specific type of certificate. */
    public boolean alreadyIssued(int participantId, String certType) throws SQLException {
        String sql = "SELECT 1 FROM certificates WHERE participant_id = ? AND cert_type = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, participantId);
            ps.setString(2, certType);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next();
            }
        }
    }

    private Certificate mapRow(ResultSet rs) throws SQLException {
        return new Certificate(
            rs.getInt("certificate_id"),
            rs.getInt("participant_id"),
            rs.getString("cert_type"),
            rs.getString("verification_code"),
            rs.getDate("issued_date").toLocalDate()
        );
    }
}
